/* eslint-disable */
import React, { useState } from "react";
import { ccc } from "@ckb-ccc/connector-react";
const signer = ccc.useSigner();



const Counter: React.FC = () => {
  const signer = ccc.useSigner();

  const [counter, setCounter] = useState<number | null>(null);
  const [txHash, setTxHash] = useState<string>("");
  const [outPoint, setOutPoint] = useState<{
    txHash: string;
    index: string;
  } | null>(null);

// connect wallet

const connectWallet = async () => {
  if (wallets.length === 0) {
    alert("No CKB wallet found");
    return;
  }
  await wallets[0].connect();
};

const disconnectWallet = async () => {
  if (!signer) return;
  await signer.disconnect();
};

  // -----------------------------
  // 1️⃣ CREATE COUNTER CELL
  // -----------------------------
  const createCounter = async () => {
    if (!signer) return;

    const { script: lock } =
      await signer.getRecommendedAddressObj();

    const tx = ccc.Transaction.from({
      outputs: [
        {
          lock,
          capacity: ccc.fixedPointFrom(61),
        },
      ],
      outputsData: [
        ccc.bytesFrom("0000000000000000"), // counter = 0
      ],
    });

    await tx.completeInputsByCapacity(signer);
    await tx.completeFeeBy(signer);

    const hash = await signer.sendTransaction(tx);

    setTxHash(hash);
    setOutPoint({
      txHash: hash,
      index: "0x0",
    });
    setCounter(0);
  };

  // -----------------------------
  // 2️⃣ INCREMENT COUNTER
  // -----------------------------
  const incrementCounter = async () => {
    if (!signer || !outPoint || counter === null) return;

    const newValue = counter + 1;

    const { script: lock } =
      await signer.getRecommendedAddressObj();

    const dataBytes = ccc.bytesFrom(
      newValue.toString(16).padStart(16, "0")
    );

    const tx = ccc.Transaction.from({
      inputs: [
        {
          previousOutput: outPoint,
        },
      ],
      outputs: [
        {
          lock,
          capacity: ccc.fixedPointFrom(61),
        },
      ],
      outputsData: [
        dataBytes,
      ],
    });

    await tx.completeFeeBy(signer);

    const hash = await signer.sendTransaction(tx);

    setTxHash(hash);
    setOutPoint({
      txHash: hash,
      index: "0x0",
    });
    setCounter(newValue);
  };

  return (
  <div style={{ padding: 16, border: "1px solid #444" }}>
    <h3>On-Chain Counter (CCC)</h3>

    {/* WALLET SECTION */}
    {!signer && (
      <button onClick={connectWallet}>
        Connect Wallet
      </button>
    )}

    {signer && (
      <button onClick={disconnectWallet}>
        Disconnect Wallet
      </button>
    )}

    <hr />

    {/* COUNTER SECTION */}
    {signer && counter === null && (
      <button onClick={createCounter}>
        Create Counter Cell
      </button>
    )}

    {signer && counter !== null && (
      <>
        <p>Counter Value: {counter}</p>
        <button onClick={incrementCounter}>
          Increment
        </button>
      </>
    )}

    {txHash && (
      <p style={{ wordBreak: "break-all" }}>
        Tx Hash: {txHash}
      </p>
    )}
  </div>
);
};

export default Counter;
